patch:
diff --git a/sql/rpl_slave.cc b/sql/rpl_slave.cc
index faa393edb9ec..5bc0a1ed491b 100644
--- a/sql/rpl_slave.cc
+++ b/sql/rpl_slave.cc
@@ -6914,16 +6914,18 @@ int start_slave(THD* thd , Master_info* mi,  bool net_report)
                  ER(ER_SLAVE_WAS_RUNNING));
   }

+  /*
+    Clean up start information if there was an attempt to start
+    the IO thread to avoid any security issue.
+  */
+  if (slave_errno &&
+      (thread_mask & SLAVE_IO) == SLAVE_IO)
+    mi->reset_start_info();
+
   unlock_slave_threads(mi);

   if (slave_errno)
   {
-    /*
-      Clean up start information if there was an attempt to start
-      the IO thread to avoid any security issue.
-    */
-    if (thread_mask & SLAVE_IO)
-      mi->reset_start_info();
     if (net_report)
       my_message(slave_errno, ER(slave_errno), MYF(0));
     DBUG_RETURN(1);
diff --git a/sql/share/errmsg-utf8.txt b/sql/share/errmsg-utf8.txt
index 3b7c96c3a6c8..a02aa0217c3c 100644
--- a/sql/share/errmsg-utf8.txt
+++ b/sql/share/errmsg-utf8.txt
@@ -6598,3 +6598,6 @@ ER_INSECURE_PLAIN_TEXT

 ER_INSECURE_CHANGE_MASTER
   eng "Storing MySQL user name or password information in the master.info repository is not secure and is therefore not recommended. Please see the MySQL Manual for more about this issue and possible alternatives."
+
+ER_SQLTHREAD_WITH_SECURE_SALVE
+  eng "Setting authentication options is not possible when only the Slave SQL Thread is being started."
diff --git a/sql/sql_yacc.yy b/sql/sql_yacc.yy
index e371918d69ce..d138831394b4 100644
--- a/sql/sql_yacc.yy
+++ b/sql/sql_yacc.yy
@@ -6951,7 +6951,22 @@ slave:
           slave_until
           {}
           slave_connection_opts
-          {}
+          {
+            /*
+              It is not possible to set user's information when
+              one is trying to start the SQL Thread.
+            */
+            if ((Lex->slave_thd_opt & SLAVE_SQL) == SLAVE_SQL &&
+                (Lex->slave_thd_opt & SLAVE_IO) != SLAVE_IO &&
+                (Lex->slave_connection.user ||
+                 Lex->slave_connection.password ||
+                 Lex->slave_connection.plugin_auth ||
+                 Lex->slave_connection.plugin_dir))
+            {
+              my_error(ER_SQLTHREAD_WITH_SECURE_SALVE, MYF(0));
+              MYSQL_YYABORT;
+            }
+          }
         | STOP_SYM SLAVE slave_thread_opts
           {
             LEX *lex=Lex;
